with with_gaps as (select *, case when event_time - lag(event_time) over (partition by session_id order by event_time asc, id asc) > interval '30' day then 1 else 0 end as is_new_session from web_events), sessionized as (select id, session_id, page, event_time, sum(is_new_session) over (partition by session_id order by event_time asc, id asc rows between unbounded preceding and current row) as island_id from with_gaps) select date_trunc('year', event_time) as year_start, date_trunc('month', event_time) as activity_month, date_trunc('quarter', event_time) as quarter_start, sort_array(collect_set(page)) as page_list, max(island_id) filter (where page = '/search') as search_max_island_id, count_if(page = '/search') as search_events, count_if(page = '/cart') as cart_events, sort_array(collect_set(page)) as page_list_2, (unix_timestamp(max(event_time)) - unix_timestamp(min(event_time))) / 60 as span_minutes from sessionized group by year_start, activity_month, quarter_start order by span_minutes asc;
